-- Table structure for table `chi_tiet_nhap`
--

DROP TABLE IF EXISTS `chi_tiet_nhap`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chi_tiet_nhap` (
  `ma_chi_tiet_nhap` int NOT NULL AUTO_INCREMENT,
  `ma_phieu_nhap` int NOT NULL,
  `ma_san_pham` int NOT NULL,
  `so_luong` int NOT NULL,
  `gia_nhap` decimal(10,2) NOT NULL,
  `gia_ban` decimal(10,2) NOT NULL,
  `so_luong_con_lai` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ma_chi_tiet_nhap`),
  UNIQUE KEY `ma_phieu_nhap` (`ma_phieu_nhap`,`ma_san_pham`),
  KEY `ma_san_pham` (`ma_san_pham`),
  CONSTRAINT `chi_tiet_nhap_ibfk_1` FOREIGN KEY (`ma_phieu_nhap`) REFERENCES `phieu_nhap` (`ma_phieu_nhap`) ON DELETE CASCADE,
  CONSTRAINT `chi_tiet_nhap_ibfk_2` FOREIGN KEY (`ma_san_pham`) REFERENCES `san_pham` (`ma_san_pham`),
  CONSTRAINT `chi_tiet_nhap_chk_1` CHECK ((`so_luong` > 0)),
  CONSTRAINT `chi_tiet_nhap_chk_2` CHECK ((`gia_nhap` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=1334 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

