  PRIMARY KEY (`ma_danh_gia`),
  KEY `danh_gia_lo_hang_ma_nhan_vien_foreign` (`ma_nhan_vien`),
  KEY `danh_gia_lo_hang_ma_chi_tiet_nhap_index` (`ma_chi_tiet_nhap`),
