CREATE TABLE `inventory_reservations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ma_hoa_don` int NOT NULL,
  `ma_san_pham` int DEFAULT NULL,
  `ma_chi_tiet_nhap` int DEFAULT NULL,
  `ma_bo_hoa` bigint unsigned DEFAULT NULL,
  `so_luong` int unsigned NOT NULL,
  `trang_thai` enum('RESERVED','CONSUMED','RELEASED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RESERVED',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `inventory_reservations_ma_hoa_don_trang_thai_index` (`ma_hoa_don`,`trang_thai`),
  KEY `inventory_reservations_ma_san_pham_trang_thai_index` (`ma_san_pham`,`trang_thai`),
  KEY `inventory_reservations_ma_chi_tiet_nhap_trang_thai_index` (`ma_chi_tiet_nhap`,`trang_thai`),
  KEY `inventory_reservations_ma_bo_hoa_trang_thai_index` (`ma_bo_hoa`,`trang_thai`),
  CONSTRAINT `inventory_reservations_ma_bo_hoa_foreign` FOREIGN KEY (`ma_bo_hoa`) REFERENCES `bo_hoa` (`ma_bo_hoa`) ON DELETE SET NULL,
  CONSTRAINT `inventory_reservations_ma_chi_tiet_nhap_foreign` FOREIGN KEY (`ma_chi_tiet_nhap`) REFERENCES `chi_tiet_nhap` (`ma_chi_tiet_nhap`) ON DELETE SET NULL,
  CONSTRAINT `inventory_reservations_ma_hoa_don_foreign` FOREIGN KEY (`ma_hoa_don`) REFERENCES `hoa_don` (`ma_hoa_don`) ON DELETE CASCADE,
  CONSTRAINT `inventory_reservations_ma_san_pham_foreign` FOREIGN KEY (`ma_san_pham`) REFERENCES `san_pham` (`ma_san_pham`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=198 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
