/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_khachhang` BEFORE INSERT ON `khach_hang` FOR EACH ROW BEGIN
    DECLARE v_role VARCHAR(20);

    SELECT vai_tro INTO v_role
    FROM nguoi_dung
    WHERE ma_nguoi_dung = NEW.ma_khach_hang;

    IF v_role <> 'KHACH_HANG' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Sai role KHACH_HANG';
    END IF;
END */;;
