CREATE TABLE `nhan_vien` (
  `ma_nhan_vien` int NOT NULL,
  `ten_nhan_vien` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `so_dien_thoai` varchar(15) DEFAULT NULL,
