  `cong_viec` text,
  `luong` decimal(15,2) DEFAULT NULL,
  `trang_thai_hoat_dong` varchar(10) NOT NULL DEFAULT 'OFFLINE',
  `nhan_don` tinyint(1) NOT NULL DEFAULT '0',
  `so_don_hien_tai` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`ma_nhan_vien`),
  CONSTRAINT `nhan_vien_ibfk_1` FOREIGN KEY (`ma_nhan_vien`) REFERENCES `nguoi_dung` (`ma_nguoi_dung`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
