/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_nhanvien` BEFORE INSERT ON `nhan_vien` FOR EACH ROW BEGIN
    DECLARE v_role VARCHAR(20);

    SELECT vai_tro INTO v_role
    FROM nguoi_dung
    WHERE ma_nguoi_dung = NEW.ma_nhan_vien;

    IF v_role NOT IN ('NHAN_VIEN', 'SHIPPER') THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Sai role NHAN_VIEN/SHIPPER';
    END IF;
END */;;
DELIMITER ;
